#include <bits/stdc++.h>
using namespace std;
const int MAX_SIZE=510;
typedef pair<int,int> PairType;
#define create_pair mp
#define get_first fi
#define get_second se

int n_value, m_value, mod_value, binom[MAX_SIZE][MAX_SIZE];
PairType dp_array[MAX_SIZE][MAX_SIZE];

int sumInterval(int start, int end) {
    return (start + end) * (end - start + 1) / 2;
}

int addModulo(int a, int b) {
    int sum = a + b;
    if (sum >= mod_value) sum -= mod_value;
    return sum;
}

PairType operator+(const PairType &a, const PairType &b) {
    return create_pair(addModulo(a.get_first, b.get_first), addModulo(a.get_second, b.get_second));
}

PairType operator*(const PairType &a, const PairType &b) {
    long long first_part = 1LL * a.get_first * b.get_first % mod_value;
    long long second_part = (1LL * a.get_first * b.get_second + 1LL * a.get_second * b.get_first) % mod_value;
    return create_pair((int)first_part, (int)second_part);
}

int main() {
#ifdef LOCAL
    freopen("a.in", "r", stdin);
    freopen("a.out", "w", stdout);
#endif
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n_value >> m_value >> mod_value;
    for (int i=0; i<MAX_SIZE; i++) {
        binom[i][0]=1;
        for (int j=1; j<=i; j++) {
            binom[i][j]=addModulo(binom[i-1][j], binom[i-1][j-1]);
        }
    }
    for (int i=0; i<=n_value; i++) {
        dp_array[i][0]=create_pair(1,0);
        for (int j=1; j<=i && j<=m_value; j++) {
            if (i!=j) {
                for (int k=1; k<=i; k++) {
                    dp_array[i][j]=dp_array[i][j]+dp_array[k-1][k-1]*dp_array[i-k][j-k+1]*create_pair(binom[j][k-1],0);
                }
            } else {
                for (int k=1; k<=i; k++) {
                    auto t1=dp_array[k-1][k-1];
                    auto t2=dp_array[i-k][i-k];
                    auto comb=create_pair(binom[i-1][k-1],0);
                    int factor= i+1 - sumInterval(1,k) + sumInterval(k+1,i) - k*(i-k);
                    auto factor_pair=create_pair(factor,0);
                    dp_array[i][j]=dp_array[i][j]+t1*t2*comb*factor_pair;
                }
            }
        }
    }
    cout<<dp_array[n_value][m_value].get_second;
    return 0;
}
